export function validateEmbedded() {
  for (const name of ['apis', 'runtime', 'hmac']) {
    if (createHash('sha256').update(SOURCES[name]).digest('hex') !== PINNED_HASHES[name]) throw Error('Pinned source mismatch');
  }
}
async function loadPinnedHelpers() {
  validateEmbedded();
  const directory = mkdtempSync(join(tmpdir(), 'garden-readiness-source-'));
  const modules = {};
  for (const name of ['apis', 'runtime', 'hmac']) {
    const path = join(directory, `bootstrap-floating-garden-${name}.mjs`);
    writeFileSync(path, SOURCES[name], { mode: 0o600, flag: 'wx' });
    modules[name] = await import(pathToFileURL(path));
  }
  return modules;
}
export function readMetadata(args, format) {
  return JSON.parse(execFileSync('gcloud', [...args, `--project=${PROJECT}`, `--billing-project=${PROJECT}`, '--verbosity=error', `--format=${format}`], {
    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000, maxBuffer: 4 * 1024 * 1024,
    // stdin is closed. Never accept an API-enablement/auth/permission prompt.
    // Match the existing reviewed helpers: no --quiet auto-confirmation.
    env: { ...process.env, CLOUDSDK_CORE_DISABLE_PROMPTS: 'false', CLOUDSDK_CORE_LOG_HTTP: 'false', CLOUDSDK_CORE_DISABLE_FILE_LOGGING: 'true', NO_COLOR: '1' },
  }));
}
// Injection is solely for isolated local tests; CLI accepts no overrides.
export async function inspectReadiness({ load = loadPinnedHelpers, read = readMetadata, log = console.log, env = process.env, execArgv = process.execArgv } = {}) {
  let stage = 'local-source';
  try {
    if (Number(process.versions.node.split('.')[0]) < 20) throw Error('Node 20+ required');
    const modules = await load();
    modules.hmac.validateEnvironment(env, execArgv);
    stage = 'apis';
    const api = await modules.apis.bootstrapApis({ apply: false, log: () => {} });
    log('APIS: ' + JSON.stringify({ complete: api.complete, missing: api.remaining }));
    log('BUILD: ' + JSON.stringify({ account: api.buildAccount, directBindings: api.bindings ?? [] }));
    if (!api.complete) throw Error('A required service is not enabled');
    stage = 'runtime';
    log('RUNTIME: ' + JSON.stringify(await modules.runtime.bootstrapRuntime({ apply: false, log: () => {} })));
    stage = 'hmac-metadata';
    const hmac = await modules.hmac.bootstrapHmac({ userOperated: false, log: (line) => {
      if (line.startsWith('EXISTING_VERSION_STATES:') || line.startsWith('DIRECT_RUNTIME_ACCESSOR:')) log(line);
    } });
    log('HMAC_EXISTS: ' + hmac.existing);
    if (hmac.existing) {
      stage = 'hmac-version-metadata';
      log('HMAC_VERSIONS: ' + JSON.stringify(read(['secrets', 'versions', 'list', 'FLOATING_GARDEN_INVITE_HMAC_KEY'], 'json(name,state)')));
      log('HMAC_LATEST_METADATA: ' + JSON.stringify(read(['secrets', 'versions', 'describe', 'latest', '--secret=FLOATING_GARDEN_INVITE_HMAC_KEY'], 'json(name,state,replicationStatus)')));
    }
    stage = 'existing-run-services';
    log('RUN_SERVICES: ' + JSON.stringify(read(['run', 'services', 'list', '--region=asia-northeast1'], 'json(metadata.name,spec.template.spec.serviceAccountName)')));
    stage = 'artifact-cleanup-metadata';
    log('ARTIFACT_REPOSITORIES: ' + JSON.stringify(read(['artifacts', 'repositories', 'list', '--location=asia-northeast1'], 'json(name,format,cleanupPolicies,cleanupPolicyDryRun)')));
    log('SNAPSHOT_ONLY: no cloud writes or secret payload access; missing fields are unknown; this does not approve or prove game readiness.');
    return { snapshotComplete: true };
  } catch {
    log(`READ_STOP: ${stage}. No cloud write was requested. Raw errors suppressed; do not change authentication or permissions.`);
    return { snapshotComplete: false, stage };
  }
}
export async function main(args = process.argv.slice(2), dependencies = {}) {
  if (!args.length || args.length === 1 && args[0] === '--plan') { (dependencies.log ?? console.log)(PLAN); return 0; }
  if (args.length !== 1 || args[0] !== '--inspect') { (dependencies.log ?? console.log)('STOP: use --plan or --inspect only.'); return 1; }
  return (await inspectReadiness(dependencies)).snapshotComplete ? 0 : 1;
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = await main();
